package local.skyfamily;
import android.app.*;import android.content.*;import android.content.pm.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
final class ShortcutPins {
 static final String KEY="sidebar.apps.v1";static final String[] ICONS={"Home","School","Games","Settings","Apps","Calendar","Notes","Create","Explore","Aquarium","Wildlife","Nature","Weather","Camera","News","Photos","Uploads"};
 static JSONArray records(PersonalActivity host)throws Exception{String raw=host.get(KEY);if(raw.length()>20000)throw new Exception("Shortcut settings too large");JSONArray list=raw.isEmpty()?new JSONArray():new JSONArray(raw);if(list.length()>8)throw new Exception("Too many shortcuts");return list;}
 static View icon(PersonalActivity host,int value){String label=ICONS[Math.max(0,Math.min(ICONS.length-1,value))];int core=CoreGlyph.kind(label),destination=DestinationIcon.kind(label);return core!=0?new CoreGlyph(host,core):destination!=0?new DestinationIcon(host,destination,PaperActivity.INK):new ControlIcon(host,label);}
 static View row(PersonalActivity host,String title,int glyph,Runnable action){host.frameRail(title,false,action);LinearLayout item=(LinearLayout)host.sidebar.getChildAt(host.sidebar.getChildCount()-1);View old=item.getChildAt(0);ViewGroup.LayoutParams size=old.getLayoutParams();item.removeViewAt(0);item.addView(icon(host,glyph),0,size);item.setTag(KEY);return item;}
 static void install(PersonalActivity host){if(host.sidebar==null||host.prefs==null)return;for(int i=host.sidebar.getChildCount()-1;i>=0;i--)if(KEY.equals(host.sidebar.getChildAt(i).getTag()))host.sidebar.removeViewAt(i);int at=host.sidebar.getChildCount();for(int i=0;i<host.sidebar.getChildCount();i++)if("Apps".contentEquals(String.valueOf(host.sidebar.getChildAt(i).getContentDescription()))){at=i+1;break;}View add=row(host,"Add app",4,()->edit(host,null));host.sidebar.removeView(add);host.sidebar.addView(add,at++);try{JSONArray list=records(host);for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);View pin=row(host,item.getString("name"),item.optInt("icon",4),()->launch(host,item.optString("component")));pin.setOnLongClickListener(view->{edit(host,item);return true;});host.sidebar.removeView(pin);host.sidebar.addView(pin,at++);}}catch(Exception error){host.toast("Cannot read saved shortcuts / existing settings retained");}host.compactShell();}
 static void launch(PersonalActivity host,String stored){try{ComponentName component=ComponentName.unflattenFromString(stored);if(component==null)throw new Exception();ActivityInfo info=host.getPackageManager().getActivityInfo(component,0);if(!info.enabled||!info.exported||!info.applicationInfo.enabled)throw new Exception();host.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(component).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED));}catch(Exception error){host.toast("App unavailable / long-press shortcut to change it");}}
 static void edit(PersonalActivity host,JSONObject original){try{records(host);}catch(Exception error){host.toast("Cannot edit damaged shortcut settings safely");return;}LinearLayout form=new LinearLayout(host);form.setOrientation(1);form.setPadding(host.dp(16),host.dp(8),host.dp(16),host.dp(8));EditText name=new EditText(host);name.setSingleLine(true);name.setHint("Shortcut name");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(24)});name.setText(original==null?"":original.optString("name"));form.addView(name);final String[] component={original==null?"":original.optString("component")};final int[] selected={original==null?4:Math.max(0,Math.min(ICONS.length-1,original.optInt("icon",4)))};Button app=new Button(host);app.setText(component[0].isEmpty()?"Choose installed app":"Change installed app");form.addView(app);app.setOnClickListener(view->apps(host,(label,target)->{component[0]=target;app.setText(label);if(name.length()==0)name.setText(label);}));Button glyph=new Button(host);glyph.setText("Icon / "+ICONS[selected[0]]);form.addView(glyph);glyph.setOnClickListener(view->{ArrayAdapter<String> adapter=new ArrayAdapter<String>(host,android.R.layout.simple_list_item_1,ICONS){public View getView(int position,View convert,ViewGroup parent){LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(host.dp(16),host.dp(8),host.dp(16),host.dp(8));row.addView(icon(host,position),new LinearLayout.LayoutParams(host.dp(26),host.dp(26)));TextView label=host.paperText(ICONS[position],18,PaperActivity.INK);label.setPadding(host.dp(16),host.dp(8),0,host.dp(8));row.addView(label);return row;}};new AlertDialog.Builder(host).setTitle("Shortcut icon").setAdapter(adapter,(dialog,index)->{selected[0]=index;glyph.setText("Icon / "+ICONS[index]);}).show();});AlertDialog.Builder builder=new AlertDialog.Builder(host).setTitle(original==null?"Add sidebar app":"Edit sidebar app").setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null);if(original!=null)builder.setNeutralButton("Remove",(dialog,which)->store(host,original,null));AlertDialog dialog=builder.create();dialog.setOnShowListener(value->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->{String title=name.getText().toString().trim();if(title.isEmpty()||component[0].isEmpty()){host.toast("Choose an app and enter a name");return;}try{JSONObject item=new JSONObject().put("id",original==null?UUID.randomUUID().toString():original.getString("id")).put("name",title).put("component",component[0]).put("icon",selected[0]);if(store(host,original,item))dialog.dismiss();}catch(Exception error){host.toast("Cannot save shortcut");}}));dialog.show();}
 static boolean store(PersonalActivity host,JSONObject original,JSONObject item){try{JSONArray previous=records(host),next=new JSONArray();for(int i=0;i<previous.length();i++){JSONObject value=previous.getJSONObject(i);if(original==null||!value.optString("id").equals(original.optString("id")))next.put(value);}if(item!=null){if(next.length()>=8)throw new Exception("Choose at most 8 shortcuts");next.put(item);}if(!host.prefs.edit().putString(KEY,next.toString()).commit())throw new Exception("Settings NOT SAVED / check storage");install(host);return true;}catch(Exception error){host.toast(error.getMessage());return false;}}
 interface Choice{void selected(String label,String component);}
 static void apps(PersonalActivity host,Choice callback){List<ResolveInfo> all=host.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);Collections.sort(all,new ResolveInfo.DisplayNameComparator(host.getPackageManager()));LinearLayout layout=new LinearLayout(host);layout.setOrientation(1);EditText search=new EditText(host);search.setHint("Search installed apps");layout.addView(search);ListView list=new ListView(host);layout.addView(list,new LinearLayout.LayoutParams(-1,host.dp(320)));ArrayList<ResolveInfo> matches=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(host,android.R.layout.simple_list_item_1,new ArrayList<String>());list.setAdapter(adapter);Runnable filter=()->{matches.clear();adapter.clear();String query=search.getText().toString().toLowerCase(Locale.getDefault());for(ResolveInfo info:all){String label=String.valueOf(info.loadLabel(host.getPackageManager()));if(info.activityInfo.enabled&&info.activityInfo.exported&&label.toLowerCase(Locale.getDefault()).contains(query)){matches.add(info);adapter.add(label);}}adapter.notifyDataSetChanged();};AlertDialog dialog=new AlertDialog.Builder(host).setTitle("Choose app").setView(layout).setNegativeButton("Cancel",null).create();list.setOnItemClickListener((parent,view,index,id)->{ResolveInfo info=matches.get(index);callback.selected(String.valueOf(info.loadLabel(host.getPackageManager())),new ComponentName(info.activityInfo.packageName,info.activityInfo.name).flattenToString());dialog.dismiss();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){filter.run();}public void afterTextChanged(Editable s){}});filter.run();dialog.show();}
}
